#ifndef TYPES_MOD
#define TYPES_MOD

/* C++ counterpart of software/mcfm/src/Mods/types_mod.f (Fortran `module types`).
 *
 * The module declares four real *kind* parameters and nothing else:
 *
 *     integer, parameter :: sp = selected_real_kind(6)
 *     integer, parameter :: dp = selected_real_kind(15)
 *     integer, parameter :: ex = selected_real_kind(18)
 *     integer, parameter :: qp = selected_real_kind(33)
 *
 * There is no value to carry over. `selected_real_kind` is a Fortran intrinsic
 * evaluated by the compiler, so the integers these parameters hold are kind
 * numbers chosen by the Fortran front end, not literals written in the source;
 * writing them out here as C++ integers would invent numbers the source does not
 * contain, and C++ has no kind system for them to select anything in.
 *
 * The precision each parameter selects is instead carried by the C++ built-in
 * type at every use site, per the translation rules: `real(dp)` becomes `double`
 * and `complex(dp)` becomes `std::complex<double>`. That is why every module
 * already rewritten in this directory drops its `use types` line, and why no
 * translated file in the tree includes a types header. This header therefore
 * declares no names on purpose: it records the module's C++ status rather than
 * introducing an interface the Fortran source never had.
 *
 * The Fortran module itself is still live and must stay in the build: 166 Fortran
 * files under src/ still `use types` for their `real(dp)` / `complex(dp)`
 * declarations. `types_mod.f` keeps its entry in Mods/CMakeLists.txt and is not
 * moved to Mods/deprecated/ — it is not obsolete, only mirrored here.
 */

namespace types_mod {
}

#endif // TYPES_MOD
