#ifndef MOD_QCDLOOP_C_MOD
#define MOD_QCDLOOP_C_MOD

#include <complex>

/* mod_qcdloop_c is a pure binding module: it holds no data and defines no
 * procedure of its own. Every name below is provided by the external QCDLoop
 * library, so this is a true C interoperability boundary and the declarations
 * stay in extern "C".
 *
 * The Fortran interfaces these mirror pass every dummy argument by reference
 * (bind(C) without the value attribute), hence the const& parameters.
 *
 * The quad precision entry points (qli1q, qli2q, qli3q, qli4q, qli1qc, qli2qc,
 * qli3qc, qli4qc) are deliberately not declared here: they need real128 /
 * __float128 types that have no standard C binding, and the original module
 * already flags that interface as broken. They remain reachable from Fortran
 * through the mod_qcdloop_c module.
 */

extern "C" {
  extern void qlcachesize(int const& csize);

  extern std::complex<double> cln(std::complex<double> const& x, double const& isig);

  extern bool qlzero(double const& x);
  extern bool qlnonzero(double const& x);

  extern std::complex<double> qli1(double const& m1, double const& mu2, int const& ep);
  extern std::complex<double> qli1c(std::complex<double> const& m1, double const& mu2, int const& ep);

  extern std::complex<double> qli2(double const& p1, double const& m1, double const& m2, double const& mu2, int const& ep);
  extern std::complex<double> qli2c(double const& p1, std::complex<double> const& m1, std::complex<double> const& m2, double const& mu2, int const& ep);

  extern std::complex<double> qli2p(double const& p1, double const& m1, double const& m2, double const& mu2, int const& ep);
  extern std::complex<double> qli2pc(double const& p1, std::complex<double> const& m1, std::complex<double> const& m2, double const& mu2, int const& ep);

  extern std::complex<double> qli3(double const& p1, double const& p2, double const& p3, double const& m1, double const& m2, double const& m3, double const& mu2, int const& ep);
  extern std::complex<double> qli3c(double const& p1, double const& p2, double const& p3, std::complex<double> const& m1, std::complex<double> const& m2, std::complex<double> const& m3, double const& mu2, int const& ep);

  extern std::complex<double> qli4(double const& p1, double const& p2, double const& p3, double const& p4, double const& s12, double const& s23, double const& m1, double const& m2, double const& m3, double const& m4, double const& mu2, int const& ep);
  extern std::complex<double> qli4c(double const& p1, double const& p2, double const& p3, double const& p4, double const& s12, double const& s23, std::complex<double> const& m1, std::complex<double> const& m2, std::complex<double> const& m3, std::complex<double> const& m4, double const& mu2, int const& ep);
}

#endif

